-- ========================================================


function DreamSpace_FirstEmotionalPieceStory:__init()
    self.controller = nil
    self.co = nil   -- 发送携程请求
    self.isInit = false
end


function DreamSpace_FirstEmotionalPieceStory:__delete()
    self.co = nil
end





function DreamSpace_FirstEmotionalPieceStory:Start()
    KTool.SetActive(self.controller.gameObject, true);
    -- ==============================
    -- 绑定 OnTriggerEnter() 函数:
    local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.OnTriggerEnterAction = function(behaviourAction,other_)
            self:OnTriggerEnter(other_)
        end
    end
    -- ==============================
    ---
    DreamSpaceLuaUtils.StopCoroutine( self.co )
    self.co = cs_coroutine.start(self.DelayInit, self)
end


function DreamSpace_FirstEmotionalPieceStory:DelayInit() 

    cs_coroutine.yield_return( DreamSpaceStory.WaitInstance() ) -- 等待实例化
    self.dreamSpaceStory = DreamSpaceStory.GetInstance()   -- 拿到唯一实例

    cs_coroutine.yield_return( DreamSpace_FullScreen.WaitInstance() ) -- 等待实例化
    self.dreamSpace_FullScreen = DreamSpace_FullScreen.GetInstance()   -- 拿到唯一实例


    PiecesCollectionUtils.OnGetFirstEmotionalPiece = function()
        DreamSpaceLuaUtils.StopCoroutine( self.co_1 )
        self.co_1 = cs_coroutine.start(self.Play, self)
    end


    self.isInit = true
end



function DreamSpace_FirstEmotionalPieceStory:OnDestroy()
    DreamSpaceLuaUtils.StopCoroutine( self.co )
    DreamSpaceLuaUtils.StopCoroutine( self.co_1 )
    self.co = nil
    self.co_1 = nil

    PiecesCollectionUtils.OnGetFirstEmotionalPiece = nil
    ---
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end


-- ===============================================================







function DreamSpace_FirstEmotionalPieceStory:Play() 
    -- 等待初始化成功:
    while self.isInit == false do
        coroutine.yield(Yielders.EndOfFrame)
    end

    DreamSpaceStates.LockSubPanelFreeInPC_ByCount( DreamSpaceStates.InputLockState.Lock ) -- PC 版 禁止打开 ui 子界面 
    DreamSpaceStates.LockInput_ByCount( DreamSpaceStates.InputLockState.Lock ) -- 希望禁止玩家输入

    -- 隐藏 DreamSpace UI:
    local RoleControllerRootCanvasMgr = import('Game.DreamSpace.UI.RoleControllerRootCanvasMgr'):GetInstance()
    RoleControllerRootCanvasMgr:ShowOrHide( false  ) -- hide
    DreamSpaceSounds.Play( DreamSpaceSounds.music.dream )

    print( "--- 第一次获得情绪碎片故事 ----" )
    cs_coroutine.yield_return( self.dreamSpaceStory:PlayStory( 1004 ) ) 


    -- 显示 DreamSpace UI:
    RoleControllerRootCanvasMgr:ShowOrHide( true  ) -- show
    DreamSpaceSounds.Stop( DreamSpaceSounds.music.dream )
    
    DreamSpaceStates.LockInput_ByCount( DreamSpaceStates.InputLockState.Unlock ) -- 解除禁止:玩家输入
    DreamSpaceStates.LockSubPanelFreeInPC_ByCount( DreamSpaceStates.InputLockState.Unlock ) -- PC 版 允许打开 ui 子界面 
end



return DreamSpace_FirstEmotionalPieceStory
